import numpy as np, fitlib
from scipy.optimize import least_squares
from scipy.signal import lfilter
names=['A_vref_op1','A_vref_op3','A_amb_op1','A_amb_op2','A_load_op2','A_gentrip_op1','A_line_op3','A_fault_op1']
Ds={n:fitlib.load(f'train/{n}.csv') for n in names}
def bil(c,K):
    N=len(c)-1; out=np.zeros(1)
    for k,ck in enumerate(c):
        term=np.array([1.0])
        for _ in range(k): term=np.polymul(term,[1,-1])
        for _ in range(N-k): term=np.polymul(term,[1,1])
        out=np.polyadd(out,ck*K**k*term)
    return out
def tf(u,b,a,dt):
    K=2/dt
    return lfilter(bil(b,K), bil(a,K), u)
def model(D,x):
    # x: K, Tq, kq_w (Q per rad/s), kp_w (P per rad/s), Tv (V filter), aP_V
    dt=D['t'][1]-D['t'][0]
    dV=D['V']-D['V0']; dS=D['S']-D['V0']; th=D['th']-D['th'][0]
    K,Tq,kqw,kpw,Tv,apv=x
    w=tf(th,[0,1,0],[1,0.1,0],dt)
    vf=tf(dV,[1,0,0],[1,Tv,0],dt) if Tv>1e-4 else dV
    Qin=K*(dS-vf)
    Q=D['Q0']+tf(Qin,[1,0,0],[1,Tq,0],dt)+kqw*w
    P=D['P0']+kpw*w+apv*dV
    return P,Q
def res(x,sel):
    r=[]
    for n in sel:
        P,Q=model(Ds[n],x); D=Ds[n]
        r.append(P-D['P']); r.append(Q-D['Q'])
    return np.concatenate(r)
